import json,glob,os
files=sorted(glob.glob('/home/runner/hub-work/.zen-agent/restored/saved-opencode-*.json'))
last=None
for p in files:
    try: d=json.load(open(p))
    except: continue
    s=d.get('sessions') or []
    pr=[x for x in s if 'pocketrun' in (x.get('directory') or '')]
    if pr: last=(p,pr)
