### Fix 1: globToRegex — `**` handling

Proper semantics (like minimatch/bash globstar):
- `**/` at start or after `/` → matches zero or more path segments: `(?:[^/]*/)*`
- `**` elsewhere → `.*`
- `*` → `[^/]*`
- `?` → `[^/]`  (currently `.` which crosses separators — bug: `?` should not match `/`)

Implementation: tokenize pattern into segments split by `/`, then build regex per segment.

```kotlin
internal fun globMatch(pattern: String, path: String): Boolean {
    val regex = buildString {
        append('^')
        val segments = pattern.split('/')
        segments.forEachIndexed { index, segment ->
            if (index > 0) {
                // the separator before this segment, unless the segment is a globstar
                if (!(index == segments.lastIndex && segment == "**") && segment != "**") append('/')
                ...
            }
        }
    }
}
```

Hmm, cleaner: build the regex by walking the pattern string, handling `**/` specially:

```kotlin
internal fun globMatch(pattern: String, path: String): Boolean {
    val regex = buildString {
        append('^')
        var i = 0
        while (i < pattern.length) {
            val c = pattern[i]
            when {
                c == '*' && pattern.getOrNull(i + 1) == '*' -> {
                    // `**/` matches zero or more directories; a trailing `**`
                    // matches everything under it.
                    if (pattern.getOrNull(i + 2) == '/') {
                        append("(?:[^/]*/)*")
                        i += 2
                    } else {
                        append(".*")
                        i++
                    }
                }
                c == '*' -> { append("[^/]*"); i++ }
                c == '?' -> { append("[^/]"); i++ }
                c in "\\^$.|+()[]{}" -> { append('\\'); append(c); i++ }
                else -> { append(c); i++ }
            }
        }
        append('$')
    }
    return Regex(regex).matches(path)
}
