/** Executes [commandLine] with [cwd] as the working directory. */
fun execute(commandLine: String, cwd: File, timeoutMs: Long = OpenCodeTools.BASH_TIMEOUT_MS): Result {
    var dir = if (cwd.isDirectory) cwd else workspace.root
    val segments = splitOps(commandLine)
    if (segments.isEmpty()) return Result(0, "")
    val out = StringBuilder()
    var lastExit = 0
    for (segment in segments) {
        // `;` always runs, `&&` only after a success, `||` only after a
        // failure — the point of a chain is to *not* run the wrong side.
        val shouldRun = when (segment.op) {
            Segment.Op.AND -> lastExit == 0
            Segment.Op.OR -> lastExit != 0
            else -> true
        }
        if (!shouldRun) continue
        val r = runPipeline(segment.command, dir, timeoutMs) { d -> dir = d }
        out.append(r.output)
        lastExit = r.exitCode
    }
    return Result(lastExit, cap(out.toString()))
}

// ---------------------------------------------------------------- structure

/** One command of a chain, with the operator that decided whether it runs. */
private class Segment(val command: String, val op: Op) {
    enum class Op { FIRST, AND, OR, SEMI }
}

/**
 * Splits on `&&`, `||` and `;` outside quotes. Pipes are left alone — they
 * belong to the pipeline, and splitting them here would lose the order.
 */
private fun splitOps(line: String): List<Segment> {
    val out = mutableListOf<Segment>()
    val cur = StringBuilder()
    var quote: Char? = null
    var pending = Segment.Op.FIRST
    var i = 0
    while (i < line.length) {
        val c = line[i]
        when {
            quote != null -> {
                cur.append(c)
                if (c == quote) quote = null
            }
            c == '"' || c == '\'' -> { quote = c; cur.append(c) }
            c == '&' && line.getOrNull(i + 1) == '&' -> {
                out.addIfNotEmpty(cur, pending)
                pending = Segment.Op.AND
                i++
            }
            c == '|' && line.getOrNull(i + 1) == '|' -> {
                out.addIfNotEmpty(cur, pending)
                pending = Segment.Op.OR
                i++
            }
            c == ';' -> {
                out.addIfNotEmpty(cur, pending)
                pending = Segment.Op.SEMI
            }
            else -> cur.append(c)
        }
        i++
    }
    out.addIfNotEmpty(cur, pending)
    return out
}

private fun MutableList<Segment>.addIfNotEmpty(cur: StringBuilder, op: Segment.Op) {
    val text = cur.toString().trim()
    if (text.isNotEmpty()) add(Segment(text, op))
    cur.clear()
}

/** Runs one `cmd | cmd | cmd [> file] [< file]` pipeline segment. */
private fun runPipeline(
    segment: String,
    dir: File,
    timeoutMs: Long,
    onCd: (File) -> Unit,
): Result {
    val stages = splitPipes(segment)
    if (stages.isEmpty()) return Result(0, "")

    var input = ""
    var exit = 0
    for (stage in stages) {
        val parsed = parseStage(tokenize(stage), dir)
        if (parsed.error != null) return Result(1, parsed.error)
        if (parsed.tokens.isEmpty()) continue
        val cmd = parsed.tokens[0]
        val args = parsed.tokens.drop(1)

        // `< file` replaces what the stage reads; otherwise it reads the
        // previous stage, and a real runtime gets the text just like a
        // built-in does — `cat data.txt | python fix.py` has to work.
        val stageInput = if (parsed.input != null) {
            if (!parsed.input.isFile) {
                return Result(1, "bash: ${parsed.input.name}: нет такого файла\n")
            }
            readCapped(parsed.input) ?: return Result(1, "bash: ${parsed.input.name}: не удалось прочитать\n")
        } else {
            input
        }

        val r = when (cmd) {
            "python", "python3" -> runPython(args, dir, timeoutMs, stageInput)
            "node" -> runNode(args, dir, timeoutMs, stageInput)
            "npx" -> runNpx(args, dir, timeoutMs, stageInput)
            "npm" -> npm(args, dir, timeoutMs)
            else -> runBuiltin(cmd, args, dir, stageInput, onCd)
        }
        exit = r.exitCode
        input = r.output
        if (parsed.output != null) {
            if (!writeToFile(parsed.output, input, parsed.append)) {
                return Result(1, "bash: ${parsed.output.name}: не удалось записать\n")
            }
            input = ""
        }
    }
    return Result(exit, input)
}

/** One pipeline stage after its redirections have been taken out. */
private class Stage(
    val tokens: List<String>,
    val output: File?,
    val append: Boolean,
    val input: File?,
    val error: String?,
)

private fun parseStage(tokens: List<String>, dir: File): Stage {
    val kept = mutableListOf<String>()
    var output: File? = null
    var append = false
    var input: File? = null
    var i = 0
    while (i < tokens.size) {
        val t = tokens[i]
        when {
            t == ">" || t == ">>" -> {
                val target = tokens.getOrNull(i + 1)
                    ?: return Stage(kept, null, false, null, "bash: $t: нужен файл\n")
                val file = sandboxPath(target, dir)
                    ?: return Stage(kept, null, false, null, "bash: $target: путь вне песочницы\n")
                output = file
                append = t == ">>"
                i++
            }
            t == "<" -> {
                val target = tokens.getOrNull(i + 1)
                    ?: return Stage(kept, null, false, null, "bash: <: нужен файл\n")
                val file = sandboxPath(target, dir)
                    ?: return Stage(kept, null, false, null, "bash: $target: путь вне песочницы\n")
                input = file
                i++
            }
            else -> kept += t
        }
        i++
    }
    return Stage(kept, output, append, input, null)
}

/** Splits on top-level `|`, honouring quotes. */
private fun splitPipes(segment: String): List<String> {
    val stages = mutableListOf<String>()
    val cur = StringBuilder()
    var quote: Char? = null
    var i = 0
    while (i < segment.length) {
        val c = segment[i]
        when {
            quote != null -> { cur.append(c); if (c == quote) quote = null }
            c == '"' || c == '\'' -> { quote = c; cur.append(c) }
            // A single `&` in the background is not supported; treating it as
            // a literal keeps `a & b` from silently meaning something else.
            c == '|' -> {
                stages += cur.toString().trim()
                cur.clear()
            }
            else -> cur.append(c)
        }
        i++
    }
    stages += cur.toString().trim()
    return stages.filter { it.isNotEmpty() }
}

