private fun headTail(args: List<String>, dir: File, fromStart: Boolean): Result {
    // head [-n N] [-N] file... — `head -n 5 f`, `head -5 f`, `head f` all
    // work, and every named file is processed: dropping the rest would look
    // successful while showing a slice of the wrong one.
    val name = if (fromStart) "head" else "tail"
    var n = 10
    val files = mutableListOf<String>()
    var i = 0
    while (i < args.size) {
        val a = args[i]
        when {
            a == "-n" && i + 1 < args.size && args[i + 1].toIntOrNull() != null ->
                n = args[++i].toInt()
            a.startsWith("-") && a.removePrefix("-").toIntOrNull() != null ->
                n = a.removePrefix("-").toInt()
            a == "--" -> files += args.drop(i + 1)
            a.startsWith("-") -> return Result(1, "$name: неизвестный аргумент $a\n")
            else -> files += a
        }
        i++
    }
    if (files.isEmpty()) return Result(1, "$name: нужен файл\n")
    val out = StringBuilder()
    var exit = 0
    val several = files.size > 1
    for (name_ in files) {
        val f = sandboxPath(name_, dir)
