private fun wc(args: List<String>, dir: File, stdin: String): Result {
    val countLines = args.any { it.contains('l') && it.startsWith("-") }
    val countWords = args.any { it.contains('w') && it.startsWith("-") }
    val countBytes = args.any { it.contains('c') && it.startsWith("-") }
    val named = flagsFree(args)
    // With no flag, wc counts lines, words and bytes — as it does on a
    // real system. Every named file is counted, and a multi-file run ends
    // with a total.
