    val files = if (named.isEmpty()) listOf<String?>(null) else named.map { it as String? }
    val out = StringBuilder()
    var exit = 0
    var totalLines = 0L
    var totalWords = 0L
    var totalBytes = 0L
    for (name in files) {
        val text = if (name == null) {
