        val lines = text.lines().let { if (text.endsWith("\n")) it.dropLast(1) else it }
        val words = text.split(Regex("\\s+")).count { it.isNotEmpty() }
        totalLines += lines.size
        totalWords += words
        totalBytes += text.length
        val parts = mutableListOf<String>()
        if (wantAll || countLines) parts += "%7d".format(lines.size)
        if (wantAll || countWords) parts += "%7d".format(words)
        if (wantAll || countBytes) parts += "%7d".format(text.length)
        out.append(parts.joinToString("")).append(' ')
        out.append(name ?: "").append('\n')
    }
    if (files.size > 1) {
        val parts = mutableListOf<String>()
        if (wantAll || countLines) parts += "%7d".format(totalLines)
        if (wantAll || countWords) parts += "%7d".format(totalWords)
        if (wantAll || countBytes) parts += "%7d".format(totalBytes)
        out.append(parts.joinToString("")).append(" total\n")
    }
    return Result(exit, out.toString())
}

