            LazyColumn(
                modifier = Modifier.weight(1f),
                verticalArrangement = Arrangement.spacedBy(8.dp),
            ) {
                items(projects, key = { it.dir.absolutePath }) { project ->
                    val isSelected = selected?.dir == project.dir
                    Card(
                        modifier = Modifier
                            .fillMaxWidth()
                            .clickable { viewModel.select(project) },
                        colors = CardDefaults.cardColors(
                            containerColor = if (isSelected) {
                                MaterialTheme.colorScheme.primaryContainer
                            } else {
                                MaterialTheme.colorScheme.surfaceVariant
                            },
                        ),
                    ) {
                        Row(
                            modifier = Modifier.fillMaxWidth().padding(start = 14.dp, end = 4.dp, top = 6.dp, bottom = 6.dp),
                            verticalAlignment = Alignment.CenterVertically,
                        ) {
                            Column(Modifier.weight(1f)) {
                                Text(
                                    project.name,
                                    style = MaterialTheme.typography.titleMedium,
                                    fontWeight = FontWeight.SemiBold,
                                )
                                Text(
                                    projectSummary(project),
                                    style = MaterialTheme.typography.bodySmall,
                                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                                )
                            }
                            IconButton(onClick = { viewModel.deleteProject(project) }) {
                                Icon(
                                    Icons.Filled.Delete,
                                    contentDescription = "Удалить проект",
                                    tint = MaterialTheme.colorScheme.error,
                                )
                            }
                        }
                    }
                }
            }
        }
        Spacer(Modifier.height(8.dp))
        Text(
            "Проект — это папка с main.py. Откройте его во вкладке «Редактор» и нажмите «Запустить».",
            style = MaterialTheme.typography.bodySmall,
            color = MaterialTheme.colorScheme.onSurfaceVariant,
        )
    }
}

private fun projectSummary(project: AppViewModel.Project): String {
    val main = File(project.dir, "main.py")
    val lines = if (main.isFile) main.readLines().size else 0
    return "main.py · $lines строк"
}

package dev.pocketrun.agent.opencode

import org.json.JSONArray
import org.json.JSONObject

/**
 * Keeps the request small enough for the model to answer.
 *
 * A long turn produces a huge history: every tool result is up to 16 KB, and a
 * few dozen rounds later the prompt is bigger than the model's context — the
 * gateway then either rejects the request (400/413) or takes minutes to answer
 * and the turn dies on a timeout. This trims the history in two steps:
 *
 * 1. tool results of older rounds shrink to a head+tail excerpt;
 * 2. if that is not enough, whole old rounds are dropped.
 *
 * Both steps keep the OpenAI invariant that every `tool` message belongs to the
 * `tool_calls` of the assistant message right before it — rounds are dropped
 * whole, never in half. The opening user message (the original request) is
 * never dropped, and nothing is modified in place: the session history stays
 * exactly as it was.
 */
object HistoryTrimmer {

    /** Roughly 30k tokens of mixed Russian/English text — comfortable for the small free models too. */
    const val DEFAULT_MAX_CHARS = 96_000

    /** How much of a single tool result survives the first pass. */
    const val TOOL_KEEP = 3_000

    private const val MARK = "\n… [сокращено: %d из %d символов]\n"

    /**
     * Returns a request-sized copy of [messages] (index 0 is the system
     * message) with the oldest, bulkiest parts removed. Returns the very same
     * array when nothing needs trimming.
     */
    fun trim(messages: JSONArray, maxChars: Int = DEFAULT_MAX_CHARS, toolKeep: Int = TOOL_KEEP): JSONArray {
        if (messages.length() <= 2) return messages
        val blocks = blocks(messages)
        // A history with an orphan `tool` message has to be rebuilt even when it
        // is small: the API rejects it whole, and the next round is the answer.
        val repaired = blocks.sumOf { it.messages.size } < messages.length() - 1
        if (!repaired && sizeOf(messages) <= maxChars) return messages
        // The system message rides along in every request, so it is part of the
        // budget even though it is never a candidate for dropping.
        val budget = (maxChars - (messages.opt(0)?.toString()?.length ?: 0)).coerceAtLeast(toolKeep)

        // Step 1: shrink the tool outputs, oldest round first.
        val shrunk = blocks.map { Block(it.messages.map { m -> shrinkTool(m, toolKeep) }, it.droppable) }
        if (sizeOf(shrunk) <= budget) return of(messages, shrunk)

        // Step 2: drop whole rounds from the oldest end, keeping the opening
        // request that carries the original task.
        val kept = ArrayList(shrunk)
        while (kept.size > 1 && sizeOf(kept) > budget) {
            val victim = kept.indexOfFirst { it.droppable }
            if (victim < 0) break
            kept.removeAt(victim)
        }
        return of(messages, kept)
    }

    // ---------------------------------------------------------------- blocks

    /** One round: a user/assistant message plus the tool results that answer it. */
    private class Block(
        val messages: List<JSONObject>,
        /** False for the opening request, which is never dropped. */
        val droppable: Boolean,
    )

    /** Groups messages into rounds; a `tool` message always joins its call. */
    private fun blocks(messages: JSONArray): List<Block> {
        val out = mutableListOf<Block>()
        val pending = LinkedHashSet<String>()
        var current = mutableListOf<JSONObject>()
        for (i in 1 until messages.length()) {
            val m = messages.optJSONObject(i) ?: continue
            when (m.optString("role")) {
                "tool" -> {
                    // Answerable only by the call that is still waiting for it.
                    // Anything else is an orphan and would be rejected by the API.
                    if (!pending.remove(m.optString("tool_call_id"))) continue
                }
                else -> {
                    m.optJSONArray("tool_calls")?.let { calls ->
                        for (c in 0 until calls.length()) {
                            calls.optJSONObject(c)?.optString("id")?.let { pending += it }
                        }
                    }
                    if (current.isNotEmpty()) {
                        out += Block(current, droppable = out.isNotEmpty())
                        current = mutableListOf()
                    }
                }
            }
            current.add(m)
        }
        if (current.isNotEmpty()) out += Block(current, droppable = out.isNotEmpty())
        return out
    }

    /** Rebuilds the request array: the system message plus the kept rounds. */
    private fun of(messages: JSONArray, blocks: List<Block>): JSONArray {
        val out = JSONArray()
        messages.opt(0)?.let { out.put(it) }
        blocks.forEach { block -> block.messages.forEach { out.put(it) } }
        return out
    }

    private fun shrinkTool(message: JSONObject, keep: Int): JSONObject {
        if (message.optString("role") != "tool") return message
        val content = message.optString("content")
        if (content.length <= keep * 2) return message
        val head = content.take(keep)
        val tail = content.takeLast(keep)
        val copy = JSONObject(message.toString())
        copy.put("content", head + String.format(MARK, head.length + tail.length, content.length) + tail)
        return copy
    }

    private fun sizeOf(messages: JSONArray): Int {
        var total = 0
        for (i in 0 until messages.length()) total += messages.opt(i)?.toString()?.length ?: 0
        return total
    }

    private fun sizeOf(blocks: List<Block>): Int =
        blocks.sumOf { block -> block.messages.sumOf { it.toString().length } }
}

package dev.pocketrun.runtime

import java.io.File
import java.io.IOException
import java.io.RandomAccessFile
import java.nio.ByteBuffer
import java.nio.CharBuffer
import java.nio.charset.CodingErrorAction
import java.nio.charset.StandardCharsets
import java.util.concurrent.atomic.AtomicBoolean

/**
 * Follows a file that another thread is appending to and reports the growth as
 * text. Python and the JS engine both write run output this way: a pipe would
 * let a slow reader block the interpreter, and a file also keeps the output if
 * the UI dies mid-run.
 */
class OutputTailer(
    private val file: File,
    private val stream: OutputStream,
    private val listener: OutputListener,
    private val stopped: AtomicBoolean,
    private val onDrained: () -> Unit,
) : Thread("pocketrun-tail-${stream.name.lowercase()}") {

    private var offset: Long = 0
    private val pending = StringBuilder()
    private val decodeBuffer = CharBuffer.allocate(1024)
    private val decoder = StandardCharsets.UTF_8.newDecoder()
        .onMalformedInput(CodingErrorAction.REPLACE)
        .onUnmappableCharacter(CodingErrorAction.REPLACE)

    /**
     * Bytes at the end of the last read that could not be decoded yet. The
     * decoder never consumes a partial multi-byte character; it leaves it in
     * the input buffer, and we have to hand it back with the next chunk.
     */
    private var undecoded = ByteArray(0)

    init {
        isDaemon = true
    }

    override fun run() {
        try {
            while (!stopped.get()) {
                if (drain()) onDrained()
                sleep(40)
            }
            drain()
        } catch (_: InterruptedException) {
            Thread.currentThread().interrupt()
        } catch (_: IOException) {
            // The run directory was deleted mid-tail; stop following instead of
            // killing the thread with an uncaught exception.
        } catch (_: SecurityException) {
            // Same story with an unreadable file.
        } finally {
            finishDecoder()
            flushPartial()
            onDrained()
        }
    }

    private fun drain(): Boolean {
        if (!file.isFile) return false
        val length = file.length()
        if (length <= offset) return false
        var grew = false
        RandomAccessFile(file, "r").use { handle ->
            handle.seek(offset)
            val chunk = ByteArray((length - offset).coerceAtMost(64L * 1024L).toInt())
            val read = handle.read(chunk)
            if (read > 0) {
                offset += read
                decodeChunk(chunk, read)
                grew = true
            }
        }
        if (grew) emitCompleteLines()
        return grew
    }

    /**
     * Incremental UTF-8 decode. The one-shot `decode(ByteBuffer)` convenience
     * method resets the decoder, so a multi-byte character split across two
     * reads would come out as U+FFFD. The ByteBuffer/CharBuffer pair leaves
     * undecodable trailing bytes in the input buffer instead; we carry those
     * over to the next chunk, so Cyrillic or emoji never gets mangled at a
     * read boundary.
     */
    private fun decodeChunk(chunk: ByteArray, length: Int) {
        val input = if (undecoded.isEmpty()) {
            ByteBuffer.wrap(chunk, 0, length)
        } else {
            ByteBuffer.allocate(undecoded.size + length).apply {
                put(undecoded)
                put(chunk, 0, length)
                flip()
            }
        }
        while (input.hasRemaining()) {
            decodeBuffer.clear()
            val result = decoder.decode(input, decodeBuffer, false)
            decodeBuffer.flip()
            if (decodeBuffer.hasRemaining()) pending.append(decodeBuffer)
            if (result.isUnderflow()) break
            // OVERFLOW: the buffer filled with input still left; go around again.
        }
        undecoded = if (input.hasRemaining()) {
            val tail = ByteArray(input.remaining())
            input.get(tail)
            tail
        } else {
            ByteArray(0)
        }
    }

    /** Decodes whatever an incomplete trailing character turns into after REPLACE. */
    private fun finishDecoder() {
        if (undecoded.isEmpty()) return
        decodeBuffer.clear()
        decoder.decode(ByteBuffer.wrap(undecoded), decodeBuffer, true)
        decodeBuffer.flip()
        if (decodeBuffer.hasRemaining()) pending.append(decodeBuffer)
        undecoded = ByteArray(0)
    }

    private fun emitCompleteLines() {
        var newline = pending.indexOf("\n")
        while (newline >= 0) {
            val line = pending.substring(0, newline).removeSuffix("\r")
            pending.delete(0, newline + 1)
            listener.onOutput(stream, line + "\n")
            newline = pending.indexOf("\n")
        }
        // A single very long line is flushed early so the UI keeps updating.
        if (pending.length > 32 * 1024) flushPartial()
    }

    private fun flushPartial() {
        if (pending.isEmpty()) return
        listener.onOutput(stream, pending.toString())
        pending.setLength(0)
    }
}

package dev.pocketrun.license

import java.nio.charset.StandardCharsets
import java.util.Base64

/**
 * Wire format for PocketRun license keys.
 *
 * A key looks like:
 *
 *     PRK1.<base64url(payload)>.<base64url(ed25519-signature)>
 *
 * The payload is a canonical line-based UTF-8 document, not JSON, so that
 * signing is byte-for-byte reproducible:
 *
 *     PRK1
 *     name=Jane Doe
 *     seat=work-laptop
 *     plan=pro
 *     nbf=1750000000
 *     exp=1760000000
 *
 * The signature covers the raw payload bytes. The verifier therefore never has
 * to re-serialize anything: it decodes the payload, verifies the signature over
 * those exact bytes, and only then parses the claims.
 *
 * This file is duplicated in the signing tool at
 * tools/keygen/src/main/kotlin/dev/pocketrun/keygen/LicenseFormat.kt.
 * Both copies are pinned to the same test vector in
 * src/test/java/dev/pocketrun/license/LicenseFormatTest.kt and
 * tools/keygen/src/test/kotlin/dev/pocketrun/keygen/LicenseFormatTest.kt,
 * so a change on one side that breaks the other fails the build.
 */
object LicenseFormat {
    const val PREFIX = "PRK1"
    const val VERSION = "PRK1"

    private const val KEY_SEPARATOR = '.'
    private val WHITESPACE = Regex("\\s+")

    private val encoder: Base64.Encoder = Base64.getUrlEncoder().withoutPadding()
    private val decoder: Base64.Decoder = Base64.getUrlDecoder()

    data class Claims(
        val name: String,
        val seat: String,
        val plan: String,
        val notBefore: Long,
        val expiresAt: Long,
    ) {
        val isTimeLimited: Boolean get() = expiresAt > 0
    }

    fun encodePayload(claims: Claims): String = buildString {
        append(VERSION).append('\n')
        append("name=").append(escape(claims.name)).append('\n')
        append("seat=").append(escape(claims.seat)).append('\n')
        append("plan=").append(escape(claims.plan)).append('\n')
        append("nbf=").append(claims.notBefore).append('\n')
        append("exp=").append(claims.expiresAt).append('\n')
    }

    fun decodePayload(payload: String): Claims {
        val lines = payload.split('\n')
        require(lines.isNotEmpty() && lines[0] == VERSION) {
            "unsupported license payload version"
        }
        val fields = HashMap<String, String>()
        for (line in lines.drop(1)) {
            if (line.isEmpty()) continue
            val eq = line.indexOf('=')
            require(eq > 0) { "malformed license field: $line" }
            fields[line.substring(0, eq)] = unescape(line.substring(eq + 1))
        }
        return Claims(
            name = fields["name"].orEmpty(),
            seat = fields["seat"].orEmpty(),
            plan = fields["plan"] ?: "trial",
            notBefore = fields["nbf"]?.toLongOrNull() ?: 0L,
            expiresAt = fields["exp"]?.toLongOrNull() ?: 0L,
        )
    }

    fun assemble(payload: String, signature: ByteArray): String {
        val body = encoder.encodeToString(payload.toByteArray(StandardCharsets.UTF_8))
        return PREFIX + KEY_SEPARATOR + body + KEY_SEPARATOR + encoder.encodeToString(signature)
    }

    /** Splits a key into its payload text and signature bytes. */
    fun split(key: String): Pair<String, ByteArray> {
        val clean = normalize(key)
        require(clean.startsWith("$PREFIX$KEY_SEPARATOR")) { "not a PocketRun license key" }
        val rest = clean.removePrefix("$PREFIX$KEY_SEPARATOR")
        val parts = rest.split(KEY_SEPARATOR)
        require(parts.size == 2 && parts.all { it.isNotEmpty() }) { "truncated license key" }
        val payload = String(decoder.decode(parts[0]), StandardCharsets.UTF_8)
        return payload to decoder.decode(parts[1])
    }

    /** Users paste keys with spaces and line breaks; the signature is over the exact bytes. */
    fun normalize(key: String): String = key.replace(WHITESPACE, "")

    fun toDisplayBlocks(key: String, blockSize: Int = 8): String =
        normalize(key).chunked(blockSize).joinToString(" ")

    private fun escape(value: String): String =
        value.replace("\\", "\\\\").replace("\n", "\\n").replace("\r", "\\r")

    private fun unescape(value: String): String {
        val out = StringBuilder(value.length)
        var i = 0
        while (i < value.length) {
            val c = value[i]
            if (c == '\\' && i + 1 < value.length) {
                when (value[i + 1]) {
                    'n' -> out.append('\n')
                    'r' -> out.append('\r')
                    '\\' -> out.append('\\')
                    else -> out.append(c).append(value[i + 1])
                }
                i += 2
            } else {
                out.append(c)
                i++
            }
        }
        return out.toString()
    }
}

