package dev.pocketrun.keygen

import java.io.File
import java.nio.charset.StandardCharsets
import java.security.PrivateKey
import java.time.Instant
import java.util.Base64

private val B64 = Base64.getUrlEncoder().withoutPadding()

private const val USAGE = """
pocketrun keygen - offline license keys for PocketRun

Commands:
  genkey [--out DIR] [--force]
      Creates a new Ed25519 signing keypair.
      Writes DIR/license.key   (private seed - keep secret, never commit)
      Writes DIR/license.pubkey (public key, paste into the app build)

  issue --name NAME --seat SEAT [--plan pro] [--days N] [--forever]
         [--key-file PATH] [--from EPOCH] [--exp EPOCH]
      Prints a signed license key.

  verify <KEY> [--key-file PATH]
      Verifies a key against the public key derived from the private seed.

  inspect <KEY>
      Decodes a key and prints its claims without verifying the signature.

  public-key --key-file PATH
      Prints the public key in the format the app build expects.
"""

fun main(args: Array<String>) {
    val options = Options.parse(args)
    if (options.positional.isEmpty() || options.flag("help")) {
        println(USAGE.trim())
        return
    }
    when (options.positional[0]) {
        "genkey" -> genKey(options)
        "issue" -> issue(options)
        "verify" -> verify(options)
        "inspect" -> inspect(options)
        "public-key" -> publicKey(options)
        else -> {
            System.err.println("unknown command: ${options.positional[0]}")
            println(USAGE.trim())
            kotlin.system.exitProcess(2)
        }
    }
}

private fun genKey(options: Options) {
    val out = File(options.value("out") ?: ".")
    val privateFile = File(out, "license.key")
    val publicFile = File(out, "license.pubkey")
    if (!options.flag("force") && (privateFile.exists() || publicFile.exists())) {
        System.err.println("refusing to overwrite existing key; pass --force")
        kotlin.system.exitProcess(1)
    }
    out.mkdirs()
    val (seed, pair) = Ed25519.generate()
    privateFile.writeText(B64.encodeToString(seed))
    publicFile.writeText(B64.encodeToString(Ed25519.encodePublicKey(pair.public)))
    println("private key -> ${privateFile.absolutePath}")
    println("public  key -> ${publicFile.absolutePath}")
    println()
    println("Put the public key into android/license.pubkey so the app verifies against it.")
}

private fun issue(options: Options) {
    val name = options.value("name") ?: error("--name is required")
    val seat = options.value("seat") ?: error("--seat is required")
    val plan = options.value("plan") ?: "pro"
    val notBefore = options.value("from")?.toLongOrNull() ?: Instant.now().epochSecond
    val expiresAt = when {
        options.flag("forever") -> 0L
        options.value("exp")?.toLongOrNull() != null -> options.value("exp")!!.toLong()
        else -> notBefore + (options.value("days")?.toLongOrNull() ?: 30L) * 86_400L
    }
    val privateKey = loadPrivateKey(options)
    val claims = LicenseFormat.Claims(
        name = name,
        seat = seat,
        plan = plan,
        notBefore = notBefore,
        expiresAt = expiresAt,
    )
    val payload = LicenseFormat.encodePayload(claims)
    val signature = Ed25519.sign(privateKey, payload.toByteArray(StandardCharsets.UTF_8))
    val key = LicenseFormat.assemble(payload, signature)
    println(LicenseFormat.toDisplayBlocks(key))
}

private fun verify(options: Options) {
    val key = options.positional.getOrNull(1) ?: error("verify needs a key argument")
    val publicKey = Ed25519.publicKeyOf(loadPrivateKey(options))
    val (payload, signature) = LicenseFormat.split(key)
    if (!Ed25519.verify(publicKey, payload.toByteArray(StandardCharsets.UTF_8), signature)) {
        System.err.println("INVALID: signature does not match")
        kotlin.system.exitProcess(1)
    }
    println("signature OK")
    printClaims(LicenseFormat.decodePayload(payload))
}

private fun inspect(options: Options) {
    val key = options.positional.getOrNull(1) ?: error("inspect needs a key argument")
    val (payload, _) = LicenseFormat.split(key)
    println("payload:")
    payload.lines().filter { it.isNotEmpty() }.forEach { println("  $it") }
    println()
    printClaims(LicenseFormat.decodePayload(payload))
}

private fun publicKey(options: Options) {
    println(B64.encodeToString(Ed25519.encodePublicKey(Ed25519.publicKeyOf(loadPrivateKey(options)))))
}

private fun printClaims(claims: LicenseFormat.Claims) {
    println("name   = ${claims.name}")
    println("seat   = ${claims.seat}")
    println("plan   = ${claims.plan}")
    println("valid  = ${Instant.ofEpochSecond(claims.notBefore)}")
    val expiry = if (claims.isTimeLimited) Instant.ofEpochSecond(claims.expiresAt).toString() else "never"
    println("expires= $expiry")
}

private fun loadPrivateKey(options: Options): PrivateKey {
    val file = File(options.value("key-file") ?: "license.key")
    check(file.isFile) { "private key not found: ${file.absolutePath}" }
    val seed = Base64.getUrlDecoder().decode(file.readText().trim().toByteArray(StandardCharsets.UTF_8))
    return Ed25519.keyPairFromSeed(seed).private
}

private class Options(val positional: List<String>, val named: Map<String, String?>) {
    fun value(name: String): String? = named[name]
    fun flag(name: String): Boolean = named.containsKey(name)

    companion object {
        fun parse(args: Array<String>): Options {
            val positional = ArrayList<String>()
            val named = LinkedHashMap<String, String?>()
            var i = 0
            while (i < args.size) {
                val arg = args[i]
                if (arg.startsWith("--")) {
                    val name = arg.removePrefix("--")
                    val next = args.getOrNull(i + 1)
                    if (next != null && !next.startsWith("--")) {
                        named[name] = next
                        i += 2
                    } else {
                        named[name] = null
                        i += 1
                    }
                } else {
                    positional += arg
                    i += 1
                }
            }
            return Options(positional, named)
        }
    }
}

package dev.pocketrun.agent.opencode

import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.js.JsRuntime
import dev.pocketrun.runtime.npm.NpxRuntime
import org.json.JSONObject
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Rule
import org.junit.Test
import org.junit.rules.TemporaryFolder
import java.io.File

/**
 * The manual-confirmation gate: read-only tools run without asking, mutating
 * tools ask the approver and respect its verdict; the github tool degrades to
 * a clear error without a token.
 */
class OpenCodeToolsGateTest {

    @get:Rule
    val tmp = TemporaryFolder()

    private fun bootSource(): String {
        val candidates = listOf(
            File("src/main/assets/node/boot.js"),
            File("app/src/main/assets/node/boot.js"),
        )
        return candidates.firstOrNull { it.isFile }?.readText(Charsets.UTF_8) ?: error("boot.js not found")
    }

    private class Harness(val tools: OpenCodeTools, val projectDir: File)

    private fun newTools(githubToken: String = ""): Harness {
        val ws = Workspace.at(tmp.newFolder())
        val project = File(ws.root, "proj").apply { mkdirs() }
        val js = JsRuntime(bootSource(), ws, maxRunMs = 10_000)
        return Harness(OpenCodeTools(ws, js, NpxRuntime(js, ws), project, githubToken), project)
    }

    @Test
    fun readOnlyToolsNeverAsk() {
        val h = newTools()
        val asked = mutableListOf<String>()
        h.tools.toolApprover = { name, _ ->
            asked += name
            true
        }
        File(h.projectDir, "a.txt").writeText("hi")
        val r = h.tools.execute("read", """{"filePath":"a.txt"}""")
        assertTrue(r.contains("hi"))
        assertTrue(asked.isEmpty())
    }

    @Test
    fun mutatingToolRespectsApproval() {
        val h = newTools()
        var verdict = false
        h.tools.toolApprover = { _, _ -> verdict }

        val denied = h.tools.execute("write", """{"filePath":"x.txt","content":"no"}""")
        assertEquals("(отклонено пользователем)", denied)
        assertFalse(File(h.projectDir, "x.txt").exists())

        verdict = true
        val allowed = h.tools.execute("write", """{"filePath":"x.txt","content":"yes"}""")
        assertTrue(allowed.contains("wrote"))
        assertEquals("yes", File(h.projectDir, "x.txt").readText())
    }

    @Test
    fun isReadOnlyClassification() {
        val tools = newTools().tools
        assertTrue(tools.isReadOnly("read", JSONObject()))
        assertTrue(tools.isReadOnly("grep", JSONObject()))
        assertTrue(tools.isReadOnly("question", JSONObject()))
        assertTrue(tools.isReadOnly("todowrite", JSONObject()))
        assertFalse(tools.isReadOnly("bash", JSONObject()))
        assertFalse(tools.isReadOnly("write", JSONObject()))
        assertFalse(tools.isReadOnly("edit", JSONObject()))
        assertFalse(tools.isReadOnly("apply_patch", JSONObject()))

        assertTrue(tools.isReadOnly("github", JSONObject().put("op", "runs")))
        assertTrue(tools.isReadOnly("github", JSONObject().put("op", "run_wait")))
        assertTrue(tools.isReadOnly("github", JSONObject().put("op", "logs")))
        assertTrue(tools.isReadOnly("github", JSONObject().put("op", "artifacts")))
        assertTrue(tools.isReadOnly("github", JSONObject().put("op", "repo_list")))
        assertTrue(tools.isReadOnly("github", JSONObject().put("op", "file_get")))
        assertTrue(tools.isReadOnly("github", JSONObject().put("op", "me")))
        assertFalse(tools.isReadOnly("github", JSONObject().put("op", "push")))
        assertFalse(tools.isReadOnly("github", JSONObject().put("op", "file_delete")))
        assertFalse(tools.isReadOnly("github", JSONObject().put("op", "repo_create")))
        assertFalse(tools.isReadOnly("github", JSONObject().put("op", "dispatch")))
        assertFalse(tools.isReadOnly("github", JSONObject().put("op", "run_cancel")))
        assertFalse(tools.isReadOnly("github", JSONObject().put("op", "api")))
    }

    @Test
    fun githubUnknownOpListsTheWaitingAndCommitOps() {
        val h = newTools(githubToken = "faketoken")
        val r = h.tools.execute("github", """{"op":"nonsense"}""")
        assertTrue(r.contains("неизвестная операция"))
        assertTrue(r.contains("repo_create"))
        assertTrue(r.contains("run_wait"))
        assertTrue(r.contains("file_delete"))
        assertTrue(r.contains("artifact_download"))
    }

    @Test
    fun toolDefinitionsCoverTheNewGithubOps() {
        val tools = newTools().tools
        val defs = tools.definitions().toString()
        assertTrue(defs.contains("run_wait"))
        assertTrue(defs.contains("run_cancel"))
        assertTrue(defs.contains("file_delete"))
        assertTrue(defs.contains("timeout_sec"))
        // The description must tell the model not to poll.
        assertTrue(defs.contains("run_wait"))
        assertTrue(defs.contains("ONE commit"))
    }

    @Test
    fun bashTimeoutIsGenerousEnoughForInstalls() {
        assertTrue(OpenCodeTools.BASH_TIMEOUT_MS >= 300_000L)
        val h = newTools()
        val r = h.tools.execute("bash", """{"command":"echo ok","timeout":999999}""")
        assertTrue(r.contains("ok"))
    }

    @Test
    fun githubWithoutTokenIsAClearError() {
        val h = newTools(githubToken = "")
        h.tools.toolApprover = { _, _ -> true }
        val r = h.tools.execute("github", """{"op":"repo_list"}""")
        assertTrue(r.contains("GitHub-токен не задан"))
        assertTrue(r.contains("⚙"))
    }

    @Test
    fun approverSeesTheToolName() {
        val h = newTools()
        val seen = mutableListOf<String>()
        h.tools.toolApprover = { name, _ ->
            seen += name
            false
        }
        h.tools.execute("bash", """{"command":"echo hi"}""")
        assertEquals(listOf("bash"), seen)
    }
}

