package dev.pocketrun.core

import android.content.Context
import java.io.File

/**
 * Every path the app touches lives under one of these roots. User code can reach
 * them through the `fs` module and the Python `os` module, but nothing outside
 * the sandbox is exposed, and [resolve] refuses to escape it.
 */
class Workspace private constructor(val root: File) {

    val projects: File get() = File(root, "projects").apply { mkdirs() }
    val packages: File get() = File(root, "packages").apply { mkdirs() }
    val cache: File get() = File(root, "cache").apply { mkdirs() }
    val logs: File get() = File(root, "logs").apply { mkdirs() }

    fun projectDir(name: String): File {
        // Unicode letters and digits survive, everything else becomes '_'.
        val safe = name.replace(Regex("[^\\p{L}\\p{N}._-]"), "_").trim('.', '_')
            .ifEmpty { "project" }
        return File(projects, safe).apply { mkdirs() }
    }

    /**
     * Resolves [candidate] against [base], returning null when it would leave the
     * sandbox. Callers treat null as "path rejected" rather than "file missing".
     */
    fun resolve(candidate: String, base: File = root): File? {
        val target = File(candidate).let { if (it.isAbsolute) it else File(base, candidate) }
        val normalized = normalize(target.absolutePath)
        val normalizedRoot = normalize(root.absolutePath)
        if (normalized != normalizedRoot && !normalized.startsWith("$normalizedRoot${File.separator}")) {
            return null
        }
        return File(normalized)
    }

    fun relativeTo(file: File): String {
        val path = normalize(file.absolutePath)
        val prefix = normalize(root.absolutePath)
        return when {
            path == prefix -> ""
            path.startsWith("$prefix${File.separator}") -> path.removePrefix("$prefix${File.separator}")
            else -> path
        }
    }

    private fun normalize(path: String): String {
        val canonical = File(path).toPath().normalize()
        return canonical.toString().trimEnd(File.separatorChar).ifEmpty { File.separator }
    }

    companion object {
        fun from(context: Context): Workspace = Workspace(
            File(context.filesDir, "workspace"),
        )

        /** JVM-friendly constructor for unit tests: the sandbox rooted at [dir]. */
        fun at(dir: File): Workspace = Workspace(dir.apply { mkdirs() })
    }
}

package dev.pocketrun.runtime

import java.io.File
import java.io.IOException
import java.io.RandomAccessFile
import java.nio.ByteBuffer
import java.nio.CharBuffer
import java.nio.charset.CodingErrorAction
import java.nio.charset.StandardCharsets
import java.util.concurrent.atomic.AtomicBoolean

/**
 * Follows a file that another thread is appending to and reports the growth as
 * text. Python and the JS engine both write run output this way: a pipe would
 * let a slow reader block the interpreter, and a file also keeps the output if
 * the UI dies mid-run.
 */
class OutputTailer(
    private val file: File,
    private val stream: OutputStream,
    private val listener: OutputListener,
    private val stopped: AtomicBoolean,
    private val onDrained: () -> Unit,
) : Thread("pocketrun-tail-${stream.name.lowercase()}") {

    private var offset: Long = 0
    private val pending = StringBuilder()
    private val decodeBuffer = CharBuffer.allocate(1024)
    private val decoder = StandardCharsets.UTF_8.newDecoder()
        .onMalformedInput(CodingErrorAction.REPLACE)
        .onUnmappableCharacter(CodingErrorAction.REPLACE)

    /**
     * Bytes at the end of the last read that could not be decoded yet. The
     * decoder never consumes a partial multi-byte character; it leaves it in
     * the input buffer, and we have to hand it back with the next chunk.
     */
    private var undecoded = ByteArray(0)

    init {
        isDaemon = true
    }

    override fun run() {
        try {
            while (!stopped.get()) {
                if (drain()) onDrained()
                sleep(40)
            }
            drain()
        } catch (_: InterruptedException) {
            Thread.currentThread().interrupt()
        } catch (_: IOException) {
            // The run directory was deleted mid-tail; stop following instead of
            // killing the thread with an uncaught exception.
        } catch (_: SecurityException) {
            // Same story with an unreadable file.
        } finally {
            finishDecoder()
            flushPartial()
            onDrained()
        }
    }

    private fun drain(): Boolean {
        if (!file.isFile) return false
        val length = file.length()
        if (length <= offset) return false
        var grew = false
        RandomAccessFile(file, "r").use { handle ->
            handle.seek(offset)
            val chunk = ByteArray((length - offset).coerceAtMost(64L * 1024L).toInt())
            val read = handle.read(chunk)
            if (read > 0) {
                offset += read
                decodeChunk(chunk, read)
                grew = true
            }
        }
        if (grew) emitCompleteLines()
        return grew
    }

    /**
     * Incremental UTF-8 decode. The one-shot `decode(ByteBuffer)` convenience
     * method resets the decoder, so a multi-byte character split across two
     * reads would come out as U+FFFD. The ByteBuffer/CharBuffer pair leaves
     * undecodable trailing bytes in the input buffer instead; we carry those
     * over to the next chunk, so Cyrillic or emoji never gets mangled at a
     * read boundary.
     */
    private fun decodeChunk(chunk: ByteArray, length: Int) {
        val input = if (undecoded.isEmpty()) {
            ByteBuffer.wrap(chunk, 0, length)
        } else {
            ByteBuffer.allocate(undecoded.size + length).apply {
                put(undecoded)
                put(chunk, 0, length)
                flip()
            }
        }
        while (input.hasRemaining()) {
            decodeBuffer.clear()
            val result = decoder.decode(input, decodeBuffer, false)
            decodeBuffer.flip()
            if (decodeBuffer.hasRemaining()) pending.append(decodeBuffer)
            if (result.isUnderflow()) break
            // OVERFLOW: the buffer filled with input still left; go around again.
        }
        undecoded = if (input.hasRemaining()) {
            val tail = ByteArray(input.remaining())
            input.get(tail)
            tail
        } else {
            ByteArray(0)
        }
    }

    /** Decodes whatever an incomplete trailing character turns into after REPLACE. */
    private fun finishDecoder() {
        if (undecoded.isEmpty()) return
        decodeBuffer.clear()
        decoder.decode(ByteBuffer.wrap(undecoded), decodeBuffer, true)
        decodeBuffer.flip()
        if (decodeBuffer.hasRemaining()) pending.append(decodeBuffer)
        undecoded = ByteArray(0)
    }

    private fun emitCompleteLines() {
        var newline = pending.indexOf("\n")
        while (newline >= 0) {
            val line = pending.substring(0, newline).removeSuffix("\r")
            pending.delete(0, newline + 1)
            listener.onOutput(stream, line + "\n")
            newline = pending.indexOf("\n")
        }
        // A single very long line is flushed early so the UI keeps updating.
        if (pending.length > 32 * 1024) flushPartial()
    }

    private fun flushPartial() {
        if (pending.isEmpty()) return
        listener.onOutput(stream, pending.toString())
        pending.setLength(0)
    }
}

package dev.pocketrun.runtime.python

import android.content.Context
import android.util.Log
import com.chaquo.python.Python
import com.chaquo.python.android.AndroidPlatform
import dev.pocketrun.core.Workspace
import dev.pocketrun.runtime.ExecRequest
import dev.pocketrun.runtime.ExecResult
import dev.pocketrun.runtime.ExecutionHandle
import dev.pocketrun.runtime.OutputListener
import dev.pocketrun.runtime.OutputTailer
import dev.pocketrun.runtime.OutputStream
import java.io.File
import java.util.UUID
import java.util.concurrent.ExecutorService
import java.util.concurrent.Executors
import java.util.concurrent.atomic.AtomicBoolean

/**
 * The CPython runtime. Chaquopy keeps one interpreter per process, so it is
 * started once from [initAsync] (about a second; never on the main thread) and
 * every [execute] afterwards reuses it.
 *
 * Scripts talk to the UI through files, not pipes: the Python bootstrap
 * (pocketrun.py) appends stdout/stderr to log files in the workspace cache and
 * two [OutputTailer]s stream them back as text.
 */
object PythonRuntime {

    private const val TAG = "PythonRuntime"
    private const val MAX_CAPTURE = 256 * 1024
    private const val TAILER_JOIN_MS = 2_000L

    private val lock = Any()

    @Volatile private var python: Python? = null
    @Volatile private var version: String? = null
    @Volatile private var runsDir: File? = null

    private val executor: ExecutorService = Executors.newSingleThreadExecutor { runnable ->
        Thread(runnable, "pocketrun-python-run").apply { isDaemon = true }
    }

    /** Starts CPython once. Safe to call again; returns immediately. */
    fun initAsync(context: Context) {
        if (python != null) return
        Thread({
            try {
                synchronized(lock) {
                    if (python == null) {
                        val appContext = context.applicationContext
                        Python.start(AndroidPlatform(appContext))
                        val py = Python.getInstance()
                        runsDir = File(Workspace.from(appContext).cache, "runs").apply { mkdirs() }
                        version = readVersion(py)
                        python = py
                        Log.i(TAG, "Python started ($version)")
                    }
                }
            } catch (t: Throwable) {
                Log.e(TAG, "Python failed to start", t)
            }
        }, "pocketrun-python-start").apply { isDaemon = true }.start()
    }

    fun isAvailable(): Boolean = python != null

    fun version(): String? = version

    private fun readVersion(py: Python): String? = try {
        py.getModule("pocketrun")
            .callAttr("interpreter_info")
            .get("version")
            .toString()
    } catch (t: Throwable) {
        Log.w(TAG, "interpreter_info failed", t)
        null
    }

    /**
     * Runs [request.target] with CPython. [listener.onOutput] arrives from the
     * tailer threads; [listener.onFinished] / [listener.onFailed] arrive from
     * the single run thread.
     *
     * Cancellation is cooperative: Chaquopy cannot interrupt a call, so
     * [ExecutionHandle.cancel] only raises a flag, and the result is reported
     * with exit code 130 (SIGINT) once the script returns on its own.
     */
    fun execute(request: ExecRequest, listener: OutputListener): ExecutionHandle {
        val py = python
        val stopped = AtomicBoolean(false)
        val cancelled = AtomicBoolean(false)
        val running = AtomicBoolean(true)
        if (py == null) {
            running.set(false)
            listener.onFailed(IllegalStateException("Python is not running (yet)"))
            return Handle(running, cancelled)
        }

        val startedAt = System.currentTimeMillis()
        val runDir = File(runsDir ?: File(request.cwd, ".runs"), UUID.randomUUID().toString())
            .apply { mkdirs() }
        val outFile = File(runDir, "out.log")
        val errFile = File(runDir, "err.log")
        val stdout = Capture()
        val stderr = Capture()

        val outTailer = OutputTailer(outFile, OutputStream.STDOUT, CaptureListener(listener, stdout), stopped) {}
        val errTailer = OutputTailer(errFile, OutputStream.STDERR, CaptureListener(listener, stderr), stopped) {}
        outTailer.start()
        errTailer.start()

        executor.execute {
            try {
                val argsJson = org.json.JSONArray().apply { request.args.forEach { put(it) } }.toString()
                val exitCode = py.getModule("pocketrun").callAttr(
                    "run",
                    request.target,
                    argsJson,
                    request.stdin,
                    outFile.absolutePath,
                    errFile.absolutePath,
                    request.cwd?.absolutePath,
                ).toInt()

                stopped.set(true)
                outTailer.join(TAILER_JOIN_MS)
                errTailer.join(TAILER_JOIN_MS)

                listener.onFinished(
                    ExecResult(
                        exitCode = if (cancelled.get()) 130 else exitCode,
                        stdout = stdout.text(),
                        stderr = stderr.text(),
                        durationMs = System.currentTimeMillis() - startedAt,
                        truncated = stdout.truncated || stderr.truncated,
                    ),
                )
            } catch (t: Throwable) {
                stopped.set(true)
                try {
                    outTailer.join(TAILER_JOIN_MS)
                    errTailer.join(TAILER_JOIN_MS)
                } catch (_: InterruptedException) {
                    Thread.currentThread().interrupt()
                }
                listener.onFailed(t)
            } finally {
                running.set(false)
                runDir.deleteRecursively()
            }
        }
        return Handle(running, cancelled)
    }

    /**
     * Runs [request] to completion (waiting for the worker) and returns the
     * result. On timeout the run is flagged cancelled and a 124 result is
     * returned. Used by the agent's run_python tool.
     */
    fun executeSync(request: ExecRequest, timeoutMs: Long): ExecResult {
        val done = java.util.concurrent.CompletableFuture<ExecResult>()
        val handle = execute(request, object : OutputListener {
            override fun onFinished(result: ExecResult) { done.complete(result) }
            override fun onFailed(error: Throwable) { done.completeExceptionally(error) }
        })
        return try {
            done.get(timeoutMs, java.util.concurrent.TimeUnit.MILLISECONDS)
        } catch (e: java.util.concurrent.TimeoutException) {
            handle.cancel()
            ExecResult(124, "", "превышено время выполнения (${timeoutMs / 1000} с)", timeoutMs)
        } catch (e: java.util.concurrent.ExecutionException) {
            ExecResult(1, "", e.cause?.message ?: e.message ?: "ошибка запуска", 0)
        }
    }

    /** Forwards tailer output and keeps a capped copy for the final ExecResult. */
    private class CaptureListener(
        private val downstream: OutputListener,
        private val capture: Capture,
    ) : OutputListener {
        override fun onOutput(stream: OutputStream, text: String) {
            capture.append(text)
            downstream.onOutput(stream, text)
        }
    }

    private class Capture {
        private val builder = StringBuilder()
        var truncated = false
            private set

        fun append(text: String) {
            if (truncated) return
            val room = MAX_CAPTURE - builder.length
            if (room <= 0) {
                truncated = true
                return
            }
            if (text.length <= room) {
                builder.append(text)
            } else {
                builder.append(text, 0, room)
                truncated = true
            }
        }

        fun text(): String = builder.toString()
    }

    private class Handle(
        private val running: AtomicBoolean,
        private val cancelled: AtomicBoolean,
    ) : ExecutionHandle {
        override val isRunning: Boolean get() = running.get()
        override fun cancel() = cancelled.set(true)
    }
}

